from typing import List

def max_servings(Q: List[int], A: List[int], B: List[int]) -> int:
    def can_make(K: int) -> bool:
        for servings_A in range(K + 1):
            servings_B = K - servings_A
            if all(A[i] * servings_A + B[i] * servings_B <= Q[i] for i in range(len(Q))):
                return True
        return False

    L, R = 0, 10**6
    while R - L > 1:
        C = (R + L) // 2
        if can_make(C):
            L = C
        else:
            R = C

    return L
